def run(program, max_steps: int = 10_000):
    stack = []
    store = {}
    calls = []
    pc = 0
    steps = 0
    n = len(program)

    def pop():
        if not stack:
            raise StackUnderflow("operand stack empty")
        return stack.pop()

    def jump_to(target):
        if not (0 <= target <= n):
            raise BadJump(f"target {target} out of range")
        return target

