                stack.append(a // b)
            elif op == "MOD":
                if b == 0:
                    raise VMZeroDivision("MOD by zero")
                stack.append(a % b)
            elif op == "EQ":
                stack.append(1 if a == b else 0)
            elif op == "LT":
                stack.append(1 if a < b else 0)
            else:
                stack.append(1 if a > b else 0)
        elif op == "NEG":
            stack.append(-pop())
        elif op == "LOAD":
            stack.append(store.get(ins[1], 0))
        elif op == "STORE":
